// Package protojson encodes and decodes proto3 JSON for messages generated by
// protoc-gen-goalchemy, matching google.golang.org/protobuf/encoding/protojson.
//
// Marshal output equals protojson.Marshal's after removing insignificant
// whitespace: fields in declaration order, zero values of implicit-presence
// fields omitted, 64-bit integers as strings, enums by name and map keys
// sorted. Unmarshal follows protojson.UnmarshalOptions{DiscardUnknown: true},
// the options Connect clients use: unknown fields and unknown enum names are
// ignored, and either the JSON name or the proto name selects a field.
package protojson

import (
	"github.com/eugenioenko/goalchemy/std/encoding/jsonvalue"
	"github.com/eugenioenko/goalchemy/std/sort"
	"github.com/eugenioenko/goalchemy/std/strconv"
	"github.com/eugenioenko/goalchemy/std/unicode/utf8"
)

// Message is implemented by generated messages and the well-known types.
type Message interface {
	EncodeProtoJSON(e *Encoder)
	DecodeProtoJSON(d *Decoder, v jsonvalue.Value)
}

// Marshal returns the proto3 JSON encoding of m.
func Marshal(m Message) ([]byte, error) {
	e := &Encoder{}
	m.EncodeProtoJSON(e)
	if e.err != nil {
		return nil, e.err
	}
	return e.buf, nil
}

// Unmarshal decodes proto3 JSON into m, which it does not reset first.
func Unmarshal(b []byte, m Message) error {
	v, err := jsonvalue.Parse(b)
	if err != nil {
		return err
	}
	return UnmarshalValue(v, m)
}

// UnmarshalValue decodes an already parsed proto3 JSON value into m.
func UnmarshalValue(v jsonvalue.Value, m Message) error {
	d := &Decoder{}
	m.DecodeProtoJSON(d, v)
	return d.err
}

// Error describes an invalid value found while encoding or decoding.
type Error struct {
	Msg string
}

func (e *Error) Error() string { return "protojson: " + e.Msg }

type frame struct {
	array bool
	n     int
}

// Encoder accumulates one JSON document. Generated code drives it; the first
// error is kept and later writes are ignored.
type Encoder struct {
	buf   []byte
	err   error
	stack []frame
}

// Err returns the first encoding error.
func (e *Encoder) Err() error { return e.err }

// Fail records msg as the encoding error unless one is already set.
func (e *Encoder) Fail(msg string) {
	if e.err == nil {
		e.err = &Error{msg}
	}
}

func (e *Encoder) value() {
	i := len(e.stack) - 1
	if i >= 0 && e.stack[i].array {
		if e.stack[i].n > 0 {
			e.buf = append(e.buf, ',')
		}
		e.stack[i].n++
	}
}

// BeginObject starts a JSON object value.
func (e *Encoder) BeginObject() {
	e.value()
	e.buf = append(e.buf, '{')
	e.stack = append(e.stack, frame{})
}

// EndObject closes the innermost object.
func (e *Encoder) EndObject() {
	e.stack = e.stack[:len(e.stack)-1]
	e.buf = append(e.buf, '}')
}

// BeginArray starts a JSON array value.
func (e *Encoder) BeginArray() {
	e.value()
	e.buf = append(e.buf, '[')
	e.stack = append(e.stack, frame{array: true})
}

// EndArray closes the innermost array.
func (e *Encoder) EndArray() {
	e.stack = e.stack[:len(e.stack)-1]
	e.buf = append(e.buf, ']')
}

// Key writes an object member name; the member's value follows.
func (e *Encoder) Key(name string) {
	i := len(e.stack) - 1
	if e.stack[i].n > 0 {
		e.buf = append(e.buf, ',')
	}
	e.stack[i].n++
	e.buf = e.appendString(e.buf, name)
	e.buf = append(e.buf, ':')
}

// Null writes null.
func (e *Encoder) Null() {
	e.value()
	e.buf = append(e.buf, "null"...)
}

// String writes s, which must be valid UTF-8.
func (e *Encoder) String(s string) {
	e.value()
	e.buf = e.appendString(e.buf, s)
}

// Bool writes b.
func (e *Encoder) Bool(b bool) {
	e.value()
	if b {
		e.buf = append(e.buf, "true"...)
	} else {
		e.buf = append(e.buf, "false"...)
	}
}

// Int32 writes n as a JSON number.
func (e *Encoder) Int32(n int32) {
	e.value()
	e.buf = strconv.AppendInt(e.buf, int64(n), 10)
}

// Uint32 writes n as a JSON number.
func (e *Encoder) Uint32(n uint32) {
	e.value()
	e.buf = strconv.AppendUint(e.buf, uint64(n), 10)
}

// Int64 writes n as a JSON string.
func (e *Encoder) Int64(n int64) {
	e.value()
	e.buf = append(e.buf, '"')
	e.buf = strconv.AppendInt(e.buf, n, 10)
	e.buf = append(e.buf, '"')
}

// Uint64 writes n as a JSON string.
func (e *Encoder) Uint64(n uint64) {
	e.value()
	e.buf = append(e.buf, '"')
	e.buf = strconv.AppendUint(e.buf, n, 10)
	e.buf = append(e.buf, '"')
}

// Float32 writes f as a JSON number, or "NaN", "Infinity" or "-Infinity".
func (e *Encoder) Float32(f float32) {
	e.value()
	e.buf = appendFloat(e.buf, float64(f), 32)
}

// Float64 writes f as a JSON number, or "NaN", "Infinity" or "-Infinity".
func (e *Encoder) Float64(f float64) {
	e.value()
	e.buf = appendFloat(e.buf, f, 64)
}

// Bytes writes b as padded standard base64.
func (e *Encoder) Bytes(b []byte) {
	e.value()
	e.buf = append(e.buf, '"')
	e.buf = appendBase64(e.buf, b)
	e.buf = append(e.buf, '"')
}

// Enum writes name, or n when the value has no name.
func (e *Encoder) Enum(n int32, name string) {
	if name == "" {
		e.Int32(n)
		return
	}
	e.String(name)
}

// Message writes m, or {} when m is nil.
func (e *Encoder) Message(m Message) {
	if m == nil {
		e.BeginObject()
		e.EndObject()
		return
	}
	m.EncodeProtoJSON(e)
}

// SortedKeys returns the keys of a string-keyed map in protojson order.
func SortedKeys(keys []string) []string {
	sort.Strings(keys)
	return keys
}

type int64s []int64

func (s int64s) Len() int           { return len(s) }
func (s int64s) Less(i, j int) bool { return s[i] < s[j] }
func (s int64s) Swap(i, j int)      { s[i], s[j] = s[j], s[i] }

type uint64s []uint64

func (s uint64s) Len() int           { return len(s) }
func (s uint64s) Less(i, j int) bool { return s[i] < s[j] }
func (s uint64s) Swap(i, j int)      { s[i], s[j] = s[j], s[i] }

// SortInt64s sorts signed integer map keys in protojson order.
func SortInt64s(keys []int64) []int64 {
	sort.Sort(int64s(keys))
	return keys
}

// SortUint64s sorts unsigned integer map keys in protojson order.
func SortUint64s(keys []uint64) []uint64 {
	sort.Sort(uint64s(keys))
	return keys
}

func (e *Encoder) appendString(out []byte, s string) []byte {
	out = append(out, '"')
	for i := 0; i < len(s); {
		c := s[i]
		if c >= 0x80 {
			r, n := utf8.DecodeRuneInString(s[i:])
			if r == utf8.RuneError && n == 1 {
				e.Fail("invalid UTF-8 in string")
				return out
			}
			out = append(out, s[i:i+n]...)
			i += n
			continue
		}
		switch {
		case c == '"' || c == '\\':
			out = append(out, '\\', c)
		case c == '\b':
			out = append(out, '\\', 'b')
		case c == '\f':
			out = append(out, '\\', 'f')
		case c == '\n':
			out = append(out, '\\', 'n')
		case c == '\r':
			out = append(out, '\\', 'r')
		case c == '\t':
			out = append(out, '\\', 't')
		case c < ' ':
			out = append(out, '\\', 'u', '0', '0', hexDigits[c>>4], hexDigits[c&0xF])
		default:
			out = append(out, c)
		}
		i++
	}
	return append(out, '"')
}

const hexDigits = "0123456789abcdef"

func isNaN(f float64) bool { return f != f }

func isInf(f float64, sign int) bool {
	return sign >= 0 && f > maxFloat64 || sign <= 0 && f < -maxFloat64
}

const maxFloat64 = 1.79769313486231570814527423731704356798070e+308

func appendFloat(out []byte, n float64, bitSize int) []byte {
	switch {
	case isNaN(n):
		return append(out, `"NaN"`...)
	case isInf(n, 1):
		return append(out, `"Infinity"`...)
	case isInf(n, -1):
		return append(out, `"-Infinity"`...)
	}
	format := byte('f')
	abs := n
	if abs < 0 {
		abs = -abs
	}
	if abs != 0 {
		if bitSize == 64 && (abs < 1e-6 || abs >= 1e21) ||
			bitSize == 32 && (float32(abs) < 1e-6 || float32(abs) >= 1e21) {
			format = 'e'
		}
	}
	out = strconv.AppendFloat(out, n, format, -1, bitSize)
	if format == 'e' {
		k := len(out)
		if k >= 4 && out[k-4] == 'e' && out[k-3] == '-' && out[k-2] == '0' {
			out[k-2] = out[k-1]
			out = out[:k-1]
		}
	}
	return out
}

const base64Std = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

func appendBase64(dst, src []byte) []byte {
	i := 0
	for ; i+3 <= len(src); i += 3 {
		v := uint(src[i])<<16 | uint(src[i+1])<<8 | uint(src[i+2])
		dst = append(dst, base64Std[v>>18&0x3F], base64Std[v>>12&0x3F], base64Std[v>>6&0x3F], base64Std[v&0x3F])
	}
	switch len(src) - i {
	case 1:
		v := uint(src[i]) << 16
		dst = append(dst, base64Std[v>>18&0x3F], base64Std[v>>12&0x3F], '=', '=')
	case 2:
		v := uint(src[i])<<16 | uint(src[i+1])<<8
		dst = append(dst, base64Std[v>>18&0x3F], base64Std[v>>12&0x3F], base64Std[v>>6&0x3F], '=')
	}
	return dst
}

// Decoder walks parsed JSON for generated code. The first error is kept and
// later reads return zero values.
type Decoder struct {
	err error
}

// Err returns the first decoding error.
func (d *Decoder) Err() error { return d.err }

// Fail records msg as the decoding error unless one is already set.
func (d *Decoder) Fail(msg string) {
	if d.err == nil {
		d.err = &Error{msg}
	}
}

func (d *Decoder) invalid(kind, field string, v jsonvalue.Value) {
	text, _ := jsonvalue.Encode(v)
	d.Fail("invalid value for " + kind + " field " + field + ": " + string(text))
}

// Object reports whether v is an object, failing otherwise.
func (d *Decoder) Object(v jsonvalue.Value, message string) bool {
	if d.err != nil {
		return false
	}
	if v.Kind() != jsonvalue.KindObject {
		text, _ := jsonvalue.Encode(v)
		d.Fail("invalid value for message " + message + ": " + string(text))
		return false
	}
	return true
}

// Array reports whether v is an array, failing otherwise.
func (d *Decoder) Array(v jsonvalue.Value, field string) bool {
	if d.err != nil {
		return false
	}
	if v.Kind() != jsonvalue.KindArray {
		d.invalid("list", field, v)
		return false
	}
	return true
}

// Duplicate fails because a field appeared under both of its names.
func (d *Decoder) Duplicate(name string) {
	d.Fail("duplicate field " + strconv.Quote(name))
}

// OneofSet fails because a second member of the same oneof appeared.
func (d *Decoder) OneofSet(name, oneof string) {
	d.Fail("error parsing " + strconv.Quote(name) + ", oneof " + oneof + " is already set")
}

// NullElement fails on a null list element or map value of a non-Value type.
func (d *Decoder) NullElement(field string) {
	d.Fail("unexpected token null in field " + field)
}

// String decodes a string field.
func (d *Decoder) String(v jsonvalue.Value, field string) string {
	if s, ok := v.AsString(); ok {
		return s
	}
	d.invalid("string", field, v)
	return ""
}

// Bool decodes a bool field.
func (d *Decoder) Bool(v jsonvalue.Value, field string) bool {
	if b, ok := v.AsBool(); ok {
		return b
	}
	d.invalid("bool", field, v)
	return false
}

func numberText(v jsonvalue.Value) (string, bool) {
	switch v.Kind() {
	case jsonvalue.KindNumber:
		return v.Number(), true
	case jsonvalue.KindString:
		s := v.String()
		if !validNumber(s) {
			return "", false
		}
		return s, true
	}
	return "", false
}

// Int32 decodes an int32, sint32 or sfixed32 field from a number or string.
func (d *Decoder) Int32(v jsonvalue.Value, field string) int32 {
	if s, ok := numberText(v); ok {
		if digits, ok := integerDigits(s); ok {
			if n, err := strconv.ParseInt(digits, 10, 32); err == nil {
				return int32(n)
			}
		}
	}
	d.invalid("int32", field, v)
	return 0
}

// Int64 decodes an int64, sint64 or sfixed64 field from a number or string.
func (d *Decoder) Int64(v jsonvalue.Value, field string) int64 {
	if s, ok := numberText(v); ok {
		if digits, ok := integerDigits(s); ok {
			if n, err := strconv.ParseInt(digits, 10, 64); err == nil {
				return n
			}
		}
	}
	d.invalid("int64", field, v)
	return 0
}

// Uint32 decodes a uint32 or fixed32 field from a number or string.
func (d *Decoder) Uint32(v jsonvalue.Value, field string) uint32 {
	if s, ok := numberText(v); ok {
		if digits, ok := integerDigits(s); ok {
			if n, err := strconv.ParseUint(digits, 10, 32); err == nil {
				return uint32(n)
			}
		}
	}
	d.invalid("uint32", field, v)
	return 0
}

// Uint64 decodes a uint64 or fixed64 field from a number or string.
func (d *Decoder) Uint64(v jsonvalue.Value, field string) uint64 {
	if s, ok := numberText(v); ok {
		if digits, ok := integerDigits(s); ok {
			if n, err := strconv.ParseUint(digits, 10, 64); err == nil {
				return n
			}
		}
	}
	d.invalid("uint64", field, v)
	return 0
}

func parseFloat(v jsonvalue.Value, bitSize int) (float64, bool) {
	if v.Kind() == jsonvalue.KindString {
		switch v.String() {
		case "NaN":
			zero := 0.0
			return zero / zero, true
		case "Infinity":
			inf := maxFloat64
			return inf * 2, true
		case "-Infinity":
			inf := maxFloat64
			return inf * -2, true
		}
	}
	s, ok := numberText(v)
	if !ok {
		return 0, false
	}
	f, err := strconv.ParseFloat(s, bitSize)
	if err != nil {
		return 0, false
	}
	return f, true
}

// Float32 decodes a float field.
func (d *Decoder) Float32(v jsonvalue.Value, field string) float32 {
	if f, ok := parseFloat(v, 32); ok {
		return float32(f)
	}
	d.invalid("float", field, v)
	return 0
}

// Float64 decodes a double field.
func (d *Decoder) Float64(v jsonvalue.Value, field string) float64 {
	if f, ok := parseFloat(v, 64); ok {
		return f
	}
	d.invalid("double", field, v)
	return 0
}

// Bytes decodes a bytes field from standard or URL-safe base64, with or
// without padding.
func (d *Decoder) Bytes(v jsonvalue.Value, field string) []byte {
	if s, ok := v.AsString(); ok {
		if b, ok := decodeBase64(s); ok {
			return b
		}
	}
	d.invalid("bytes", field, v)
	return nil
}

// Enum decodes an enum field from its value name or number. ok is false for
// an unknown name, which proto3 JSON with DiscardUnknown ignores.
func (d *Decoder) Enum(v jsonvalue.Value, field string, values map[string]int32) (n int32, ok bool) {
	switch v.Kind() {
	case jsonvalue.KindString:
		if n, found := values[v.String()]; found {
			return n, true
		}
		return 0, false
	case jsonvalue.KindNumber:
		if digits, ok := integerDigits(v.Number()); ok {
			if n, err := strconv.ParseInt(digits, 10, 32); err == nil {
				return int32(n), true
			}
		}
	}
	d.invalid("enum", field, v)
	return 0, false
}

// MapKeyInt64 decodes a signed integer map key.
func (d *Decoder) MapKeyInt64(key string, bitSize int, field string) int64 {
	n, err := strconv.ParseInt(key, 10, bitSize)
	if err != nil {
		d.Fail("invalid value for map key of " + field + ": " + strconv.Quote(key))
	}
	return n
}

// MapKeyUint64 decodes an unsigned integer map key.
func (d *Decoder) MapKeyUint64(key string, bitSize int, field string) uint64 {
	n, err := strconv.ParseUint(key, 10, bitSize)
	if err != nil {
		d.Fail("invalid value for map key of " + field + ": " + strconv.Quote(key))
	}
	return n
}

// MapKeyBool decodes a bool map key.
func (d *Decoder) MapKeyBool(key string, field string) bool {
	switch key {
	case "true":
		return true
	case "false":
		return false
	}
	d.Fail("invalid value for map key of " + field + ": " + strconv.Quote(key))
	return false
}

func validNumber(s string) bool {
	if s == "" {
		return false
	}
	_, err := jsonvalue.Parse([]byte(s))
	if err != nil {
		return false
	}
	c := s[0]
	return c == '-' || c >= '0' && c <= '9'
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

// integerDigits normalizes a JSON number to the decimal digits of an integer,
// accepting fractions and exponents that cancel out, as protojson does.
func integerDigits(s string) (string, bool) {
	neg := false
	if s != "" && s[0] == '-' {
		neg = true
		s = s[1:]
	}
	if s == "" {
		return "", false
	}
	var intp, frac, exp string
	i := 0
	if s[0] == '0' {
		i = 1
	} else if isDigit(s[0]) {
		for i < len(s) && isDigit(s[i]) {
			i++
		}
		intp = s[:i]
	} else {
		return "", false
	}
	if i+1 < len(s) && s[i] == '.' && isDigit(s[i+1]) {
		j := i + 1
		for j < len(s) && isDigit(s[j]) {
			j++
		}
		frac = s[i+1 : j]
		i = j
	}
	if i < len(s) && (s[i] == 'e' || s[i] == 'E') {
		j := i + 1
		if j < len(s) && (s[j] == '+' || s[j] == '-') {
			j++
		}
		if j >= len(s) || !isDigit(s[j]) {
			return "", false
		}
		exp = s[i+1:]
		i = len(s)
	}
	if i != len(s) {
		return "", false
	}
	for len(frac) > 0 && frac[len(frac)-1] == '0' {
		frac = frac[:len(frac)-1]
	}
	if intp == "" && frac == "" {
		return "0", true
	}
	e := 0
	if exp != "" {
		n, err := strconv.ParseInt(exp, 10, 32)
		if err != nil {
			return "", false
		}
		e = int(n)
	}
	var num string
	if e >= 0 {
		if len(frac) > e || len(intp)+e > 20 {
			return "", false
		}
		num = intp + frac
		for k := 0; k < e-len(frac); k++ {
			num += "0"
		}
	} else {
		if len(frac) > 0 {
			return "", false
		}
		index := len(intp) + e
		if index < 0 {
			return "", false
		}
		for k := index; k < len(intp); k++ {
			if intp[k] != '0' {
				return "", false
			}
		}
		num = intp[:index]
	}
	if num == "" {
		num = "0"
	}
	if neg {
		return "-" + num, true
	}
	return num, true
}

func base64Index(c byte, url bool) int {
	switch {
	case c >= 'A' && c <= 'Z':
		return int(c - 'A')
	case c >= 'a' && c <= 'z':
		return int(c-'a') + 26
	case c >= '0' && c <= '9':
		return int(c-'0') + 52
	case !url && c == '+' || url && c == '-':
		return 62
	case !url && c == '/' || url && c == '_':
		return 63
	}
	return -1
}

func containsAny(s, chars string) bool {
	for i := 0; i < len(s); i++ {
		for j := 0; j < len(chars); j++ {
			if s[i] == chars[j] {
				return true
			}
		}
	}
	return false
}

func decodeBase64(s string) ([]byte, bool) {
	url := containsAny(s, "-_")
	padded := len(s)%4 == 0
	body := s
	if containsAny(body, "\r\n") {
		var kept []byte
		for i := 0; i < len(body); i++ {
			if body[i] != '\r' && body[i] != '\n' {
				kept = append(kept, body[i])
			}
		}
		body = string(kept)
	}
	if padded {
		for k := 0; k < 2 && len(body) > 0 && body[len(body)-1] == '='; k++ {
			body = body[:len(body)-1]
		}
	}
	if len(body)%4 == 1 {
		return nil, false
	}
	out := make([]byte, 0, len(body)*3/4)
	var acc uint
	bits := 0
	for i := 0; i < len(body); i++ {
		v := base64Index(body[i], url)
		if v < 0 {
			return nil, false
		}
		acc = acc<<6 | uint(v)
		bits += 6
		if bits >= 8 {
			bits -= 8
			out = append(out, byte(acc>>uint(bits)))
		}
	}
	return out, true
}
